CREATE TYPE "Role" AS ENUM ('SUPER_ADMIN','OPERATOR');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING','PAID','REFUSED','REFUNDED','CHARGEBACK','CANCELED');
CREATE TYPE "OrderType" AS ENUM ('ONE_TIME','RECURRING');
CREATE TYPE "PaymentMethod" AS ENUM ('credit_card','pix','boleto','paypal','other');
CREATE TYPE "ProductKind" AS ENUM ('FRONT','ORDER_BUMP','UPSELL','DOWNSELL','SUBSCRIPTION');
CREATE TYPE "SubscriptionStatus" AS ENUM ('ACTIVE','PENDING','REFUSED','RENEWED','LATE','CANCELED','PAUSED');
CREATE TYPE "SubscriptionEventType" AS ENUM ('CREATED','RENEWED','REFUSED','LATE','CANCELED','REACTIVATED');
CREATE TYPE "AccessLinkStatus" AS ENUM ('REQUESTED','GENERATED','ACCESSED','CONVERTED','EXPIRED','REVOKED');
CREATE TYPE "WebhookSource" AS ENUM ('SALES','UTMIFY','N8N');
CREATE TYPE "OutboxDestination" AS ENUM ('N8N','UTMIFY');
CREATE TYPE "OutboxStatus" AS ENUM ('PENDING','SENT','FAILED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'OPERATOR',"active" BOOLEAN NOT NULL DEFAULT true,"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"createdById" TEXT);
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"emailNormalized" TEXT NOT NULL UNIQUE,"phone" TEXT,"phoneDigits" TEXT,"document" TEXT,"documentDigits" TEXT,"externalCustomerId" TEXT,"firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY,"source" TEXT NOT NULL,"externalId" TEXT NOT NULL,"name" TEXT NOT NULL,"kind" "ProductKind" NOT NULL DEFAULT 'FRONT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("source","externalId"));
CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"source" TEXT NOT NULL,"externalOrderId" TEXT NOT NULL,"customerId" TEXT NOT NULL,"status" "OrderStatus" NOT NULL,"type" "OrderType" NOT NULL DEFAULT 'ONE_TIME',"paymentMethod" "PaymentMethod" NOT NULL,"amountCents" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'BRL',"approvedAt" TIMESTAMP(3),"refundedAt" TIMESTAMP(3),"rawPayload" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("source","externalOrderId"));
CREATE TABLE "OrderItem" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL,"productId" TEXT NOT NULL,"amountCents" INTEGER NOT NULL,"isUpsell" BOOLEAN NOT NULL DEFAULT false,"isOrderBump" BOOLEAN NOT NULL DEFAULT false,UNIQUE("orderId","productId"));
CREATE TABLE "Subscription" ("id" TEXT PRIMARY KEY,"source" TEXT NOT NULL,"externalSubscriptionId" TEXT NOT NULL,"customerId" TEXT NOT NULL,"productId" TEXT,"planName" TEXT,"frequency" TEXT,"status" "SubscriptionStatus" NOT NULL,"startedAt" TIMESTAMP(3),"nextChargeAt" TIMESTAMP(3),"lastChargeAt" TIMESTAMP(3),"lastRenewedAt" TIMESTAMP(3),"canceledAt" TIMESTAMP(3),"cycleCount" INTEGER NOT NULL DEFAULT 1,"renewalCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("source","externalSubscriptionId"));
CREATE TABLE "SubscriptionEvent" ("id" TEXT PRIMARY KEY,"subscriptionId" TEXT NOT NULL,"type" "SubscriptionEventType" NOT NULL,"orderId" TEXT,"occurredAt" TIMESTAMP(3) NOT NULL,"amountCents" INTEGER,"rawPayload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AccessLink" ("id" TEXT PRIMARY KEY,"customerId" TEXT NOT NULL,"orderId" TEXT NOT NULL,"token" TEXT UNIQUE,"url" TEXT,"label" TEXT,"status" "AccessLinkStatus" NOT NULL DEFAULT 'REQUESTED',"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"generatedAt" TIMESTAMP(3),"lastAccessedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"n8nRunId" TEXT,"metadata" JSONB);
CREATE TABLE "UpsellConversion" ("id" TEXT PRIMARY KEY,"customerId" TEXT NOT NULL,"accessLinkId" TEXT,"frontOrderId" TEXT,"upsellOrderId" TEXT NOT NULL,"productId" TEXT,"purchasedAt" TIMESTAMP(3) NOT NULL,"amountCents" INTEGER NOT NULL,UNIQUE("upsellOrderId","productId"));
CREATE TABLE "UtmSnapshot" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL UNIQUE,"src" TEXT,"sck" TEXT,"utmSource" TEXT,"utmMedium" TEXT,"utmCampaign" TEXT,"utmContent" TEXT,"utmTerm" TEXT);
CREATE TABLE "WebhookInbox" ("id" TEXT PRIMARY KEY,"source" "WebhookSource" NOT NULL,"eventType" TEXT NOT NULL,"externalKey" TEXT NOT NULL,"payload" JSONB NOT NULL,"signatureOk" BOOLEAN NOT NULL DEFAULT true,"processedAt" TIMESTAMP(3),"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("source","externalKey"));
CREATE TABLE "WebhookOutbox" ("id" TEXT PRIMARY KEY,"destination" "OutboxDestination" NOT NULL,"eventType" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" "OutboxStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"lastError" TEXT,"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"userId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"meta" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Customer_documentDigits_idx" ON "Customer"("documentDigits"); CREATE INDEX "Customer_phoneDigits_idx" ON "Customer"("phoneDigits"); CREATE INDEX "Order_status_approvedAt_idx" ON "Order"("status","approvedAt"); CREATE INDEX "Order_customerId_idx" ON "Order"("customerId"); CREATE INDEX "Subscription_status_lastRenewedAt_idx" ON "Subscription"("status","lastRenewedAt"); CREATE INDEX "Subscription_customerId_idx" ON "Subscription"("customerId"); CREATE INDEX "AccessLink_orderId_idx" ON "AccessLink"("orderId"); CREATE INDEX "AccessLink_customerId_status_idx" ON "AccessLink"("customerId","status"); CREATE INDEX "WebhookInbox_createdAt_idx" ON "WebhookInbox"("createdAt"); CREATE INDEX "WebhookOutbox_status_createdAt_idx" ON "WebhookOutbox"("status","createdAt");
ALTER TABLE "User" ADD CONSTRAINT "User_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Subscription" ADD CONSTRAINT "Subscription_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Subscription" ADD CONSTRAINT "Subscription_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SubscriptionEvent" ADD CONSTRAINT "SubscriptionEvent_subscriptionId_fkey" FOREIGN KEY ("subscriptionId") REFERENCES "Subscription"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SubscriptionEvent" ADD CONSTRAINT "SubscriptionEvent_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AccessLink" ADD CONSTRAINT "AccessLink_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "AccessLink" ADD CONSTRAINT "AccessLink_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "UpsellConversion" ADD CONSTRAINT "UpsellConversion_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "UpsellConversion" ADD CONSTRAINT "UpsellConversion_accessLinkId_fkey" FOREIGN KEY ("accessLinkId") REFERENCES "AccessLink"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "UpsellConversion" ADD CONSTRAINT "UpsellConversion_frontOrderId_fkey" FOREIGN KEY ("frontOrderId") REFERENCES "Order"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "UpsellConversion" ADD CONSTRAINT "UpsellConversion_upsellOrderId_fkey" FOREIGN KEY ("upsellOrderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "UtmSnapshot" ADD CONSTRAINT "UtmSnapshot_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
